package app.meltype.onnxprobe

import ai.onnxruntime.OnnxTensor
import ai.onnxruntime.OrtEnvironment
import ai.onnxruntime.OrtSession
import java.io.Closeable
import java.io.File

/**
 * Local ONNX Runtime CPUExecutionProvider only. No CUDA, DirectML, NNAPI, or HTTP.
 *
 * Expects Fumiori's ONNX dual encoder:
 *   int64 input_ids[batch, sequence]
 *   int64 attention_mask[batch, sequence]
 *   float embeddings[batch, 384]
 * Callers MUST provide IDs generated by the exact matching tokenizer.json.
 */
class OnnxCpuEncoder(modelFile: File, threads: Int = 2) : TokenEmbeddingEncoder, Closeable {
    private val env = OrtEnvironment.getEnvironment()
    private val options = OrtSession.SessionOptions().apply {
        setIntraOpNumThreads(threads.coerceIn(1, 4))
        setOptimizationLevel(OrtSession.SessionOptions.OptLevel.ALL_OPT)
    }
    private val session: OrtSession

    init {
        require(modelFile.isFile && modelFile.length() > 0L) { "ONNX model missing" }
        try {
            session = env.createSession(modelFile.absolutePath, options)
            require("input_ids" in session.inputNames && "attention_mask" in session.inputNames) {
                "Unsupported ONNX graph inputs"
            }
        } catch (t: Throwable) {
            options.close()
            throw t
        }
    }

    @Synchronized
    override fun encode(tokens: TokenSequence): FloatArray {
        // The Kotlin arrays are copied into native buffers by ORT.
        OnnxTensor.createTensor(env, arrayOf(tokens.inputIds)).use { ids ->
            OnnxTensor.createTensor(env, arrayOf(tokens.attentionMask)).use { mask ->
                session.run(mapOf("input_ids" to ids, "attention_mask" to mask)).use { result ->
                    val rows = result[0].value as? Array<*>
                        ?: error("ONNX output is not a float matrix")
                    val embedding = rows.firstOrNull() as? FloatArray
                        ?: error("ONNX embedding is not float32")
                    return embedding.copyOf()
                }
            }
        }
    }

    override fun close() {
        session.close()
        options.close()
    }
}
